import React from 'react';
import { previewResourceOutcome } from './votingUtils.js';
import './Events.css';

/**
 * Module-scoped set of scenario IDs that have already been acknowledged.
 *
 * Stored outside the component so the guard survives unmount / remount cycles.
 * A new scenario always has a fresh unique ID (generated by EventsContainer),
 * so loading a different event automatically re-enables the button.
 */
const acknowledgedScenarioIds = new Set();

/**
 * Returns user-friendly metadata for each life-support resource.
 *
 * @param {'oxygen'|'power'|'food'|'radiation'} key
 * @returns {{ name: string, icon: string, unit: string, isHazard: boolean }}
 */
function getResourceMeta(key) {
  switch (key) {
    case 'oxygen':
      return { name: 'Atmospheric Oxygen', icon: '🫧', unit: '%', isHazard: false };
    case 'power':
      return { name: 'Core Power Grid', icon: '⚡', unit: '%', isHazard: false };
    case 'food':
      return { name: 'Food Rations', icon: '🌱', unit: '%', isHazard: false };
    case 'radiation':
      return { name: 'Radiation Exposure', icon: '☢️', unit: '%', isHazard: true };
    default:
      return { name: key, icon: '📊', unit: '%', isHazard: false };
  }
}

/**
 * Evaluates whether a delta represents a positive benefit or negative hazard.
 *
 * @param {number} value
 * @param {boolean} isHazard - True for radiation (higher is dangerous).
 * @returns {{ type: 'gain'|'loss'|'neutral', formatted: string }}
 */
function evaluateDeltaImpact(value, isHazard) {
  const num = typeof value === 'number' && Number.isFinite(value) ? value : 0;
  if (num === 0) {
    return { type: 'neutral', formatted: '0%' };
  }

  const sign = num > 0 ? `+${num}%` : `${num}%`;
  // For hazard (radiation), positive = loss/danger; negative = gain/safety
  // For standard resources, positive = gain; negative = loss
  const isBeneficial = isHazard ? num < 0 : num > 0;

  return {
    type: isBeneficial ? 'gain' : 'loss',
    formatted: sign,
  };
}

/**
 * EventResolution Component
 *
 * Displays the finalized outcome of a Martian crisis decision:
 * - Winning strategic option and description.
 * - Resolution pathway badge (Consensus Majority, Commander Tie-Breaker, or Lowest-Risk Fallback).
 * - Exact resource changes for oxygen, power, food, and radiation with clear gain/loss cues.
 * - Projected resource telemetry when currentResources is supplied via previewResourceOutcome().
 *
 * Pure presentation: does not directly mutate mission state or life-support reserves.
 *
 * @param {Object} props
 * @param {Object} [props.scenario] - Resolved voting scenario object.
 * @param {Object} [props.currentResources] - Optional active resources { oxygen, power, food, radiation } to preview outcomes.
 * @param {Function} [props.onAcknowledge] - Callback fired when the crew acknowledges outcome: (appliedDelta) => void.
 * @param {string} [props.confirmLabel='Acknowledge & Ingest Telemetry'] - Action button text.
 */
export function EventResolution({
  scenario = null,
  currentResources = null,
  onAcknowledge,
  confirmLabel = 'Acknowledge & Ingest Telemetry',
}) {
  if (!scenario || !scenario.event) {
    return (
      <div className="event-resolution-container">
        <p className="briefing-description-text">No resolved decision data available.</p>
      </div>
    );
  }

  const event = scenario.event;
  const winningOption =
    scenario.winningOption ||
    (event.options && event.options.find((o) => o.id === scenario.resolvedOptionId)) ||
    null;

  const appliedDelta = scenario.appliedDelta || winningOption?.delta || {
    oxygen: 0,
    power: 0,
    food: 0,
    radiation: 0,
  };

  // Preview projected resources if current values are provided
  const projectedResources = currentResources
    ? previewResourceOutcome(currentResources, appliedDelta)
    : null;

  // Determine decision path / tie-break mechanism
  const tieBrokenBy = scenario.tieBrokenBy || null;
  let methodBadge = {
    icon: '🗳️',
    label: 'CREW MAJORITY DECISION',
    desc: 'Protocol adopted by crew consensus.',
  };

  if (tieBrokenBy) {
    if (tieBrokenBy.toLowerCase().includes('commander')) {
      methodBadge = {
        icon: '⭐',
        label: 'COMMANDER TIE-BREAKER',
        desc: `Vote deadlock broken by ${tieBrokenBy}.`,
      };
    } else {
      methodBadge = {
        icon: '🛡️',
        label: 'CONSERVATIVE EMERGENCY FALLBACK',
        desc: 'Automated protocol selected the lowest-risk operational path.',
      };
    }
  }

  const resourceKeys = ['oxygen', 'power', 'food', 'radiation'];

  // --- One-time acknowledgement guard ---
  // Build a stable key from the scenario ID. If (unlikely) no ID is present,
  // fall back to a composite so the guard still works.
  const scenarioKey = scenario.id ?? `${scenario.event?.id ?? 'evt'}-${scenario.resolvedOptionId ?? 'none'}`;
  const isAcknowledged = acknowledgedScenarioIds.has(scenarioKey);

  /**
   * Fires onAcknowledge exactly once per scenario.
   * Subsequent clicks while the same scenario is loaded are silently ignored.
   */
  const handleAcknowledge = () => {
    if (isAcknowledged) return;
    acknowledgedScenarioIds.add(scenarioKey);
    if (typeof onAcknowledge === 'function') {
      onAcknowledge(appliedDelta);
    }
  };
  // --------------------------------------

  return (
    <div className="event-resolution-container" role="region" aria-label="Crisis Resolution Dispatch">
      {/* Resolution Top Banner */}
      <header className="resolution-header-banner">
        <div className="resolution-title-group">
          <span className="modal-event-category">Incident Resolved // Sol Dispatch</span>
          <h3>{event.title}</h3>
        </div>

        <div className="resolution-method-badge" title={methodBadge.desc}>
          <span aria-hidden="true">{methodBadge.icon}</span>
          <span>{methodBadge.label}</span>
        </div>
      </header>

      {/* Selected Strategic Option Spotlight */}
      {winningOption ? (
        <section className="selected-decision-card" aria-label="Adopted Directive">
          <span className="selected-card-tag">Adopted Survival Protocol</span>
          <h4 className="selected-decision-title">{winningOption.title}</h4>
          <p className="selected-decision-desc">{winningOption.description}</p>
        </section>
      ) : (
        <div className="selected-decision-card">
          <p className="selected-decision-desc">
            Protocol ID: {scenario.resolvedOptionId || 'Default Emergency Protocol'}
          </p>
        </div>
      )}

      {/* Resource Impact Telemetry Breakdown */}
      <section className="resource-impact-section" aria-label="Telemetry Impact Telemetry">
        <div className="options-section-label">
          <span>Habitat Resource Delta // Ingest</span>
          <span className="options-count-badge">ECLSS Telemetry</span>
        </div>

        <div className="impact-grid">
          {resourceKeys.map((key) => {
            const meta = getResourceMeta(key);
            const deltaVal = appliedDelta[key] ?? 0;
            const impact = evaluateDeltaImpact(deltaVal, meta.isHazard);
            const curVal = currentResources ? (currentResources[key] ?? 0) : null;
            const projVal = projectedResources ? projectedResources[key] : null;

            return (
              <div key={key} className="impact-metric-card">
                <div className="impact-card-top">
                  <span className="impact-resource-name">
                    <span aria-hidden="true" style={{ marginRight: '0.35rem' }}>{meta.icon}</span>
                    {meta.name}
                  </span>
                  <span className={`impact-delta-pill ${impact.type}`}>
                    {impact.formatted}
                  </span>
                </div>

                {/* Projected Value Row (when currentResources supplied) */}
                {curVal !== null && projVal !== null && (
                  <div className="impact-projection-row">
                    <span className="proj-current-val">{curVal}%</span>
                    <span className="proj-arrow" aria-hidden="true">&rarr;</span>
                    <span className="proj-new-val">{projVal}%</span>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </section>

      {/* Confirmation / Acknowledge Action Button */}
      {typeof onAcknowledge === 'function' && (
        <footer className="voting-actions-bar" style={{ justifyContent: 'flex-end' }}>
          <button
            type="button"
            className="btn-mars-primary"
            disabled={isAcknowledged}
            onClick={handleAcknowledge}
          >
            {isAcknowledged ? '✓ Telemetry Ingested' : `${confirmLabel} →`}
          </button>
        </footer>
      )}
    </div>
  );
}

export default EventResolution;
